+        assert!(first.status.success(), "Python execute failed: {}", stderr_of(&first));
+        assert_python_receipt(&receipt, &intent, "published", &revision);
+        assert_eq!(
+            git(dir.path(), &["rev-parse", &format!("refs/tags/{TAG}^{{commit}}")]),
