312	/// Refuses when a canonical manifest version differs from `HEAD` while release inputs remain or the change is staged.
313	pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
314	    let head = match ws.git_access().head_sha() {
315	        Ok(head) => head,
316	        Err(error) => {
317	            let output = ws
318	                .runner
319	                .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &ws.root)
320	                .map_err(GraphError::Command)?;
321	            match output.exit_code {
322	                Some(1) => return Ok(()),
323	                Some(0) => return Err(error.into()),
324	                exit_code => {
325	                    return Err(GraphError::Command(callisto_model::CommandError::Failed {
326	                        program: "git".to_string(),
327	                        exit_code,
328	                        stderr: output.stderr,
329	                    }))
330	                }
331	            }
332	        }
333	    };
334	    let head = head.as_str();
335	
336	    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
337	    let pre_mode = {
338	        let path = ws.root.join(ws.config.pre_json_path());
339	        if path.exists() {
340	            let text =
341	                std::fs::read_to_string(&path).map_err(|e| GraphError::PreJsonRead { message: e.to_string() })?;
342	            let state = callisto_model::format::parse_pre_json(&text).map_err(GraphError::PreJson)?;
343	            Some(state.mode)
344	        } else {
345	            None
346	        }
347	    };
348	    let in_pre_release_cycle = pre_mode == Some(callisto_model::format::PreMode::Pre);
349	
350	    let staged_manifests = if in_pre_release_cycle {
351	        BTreeSet::new()
352	    } else {
353	        canonical_manifest_staged_paths(ws)?
354	    };
355	    let pending = !in_pre_release_cycle
356	        && (head_has_pending_changeset(ws, head)?
357	            || working_tree_has_pending_changeset(ws)?
358	            || !staged_manifests.is_empty());
359	    if !pending {
360	        return Ok(());
361	    }
362	
363	    let cargo_root = if ws
364	        .graph
365	        .packages()
366	        .flat_map(|pkg| pkg.canonical_manifests())
367	        .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
368	    {
369	        manifest_blob_at(ws, head, "Cargo.toml")?
370	    } else {
371	        None
372	    };
373	    let cargo_index_needed = !staged_manifests.is_empty()
374	        && ws.graph.packages().any(|pkg| {
375	            pkg.canonical_manifests()
376	                .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
377	        });
378	    let cargo_root_index = if cargo_index_needed {
379	        manifest_blob_in_index(ws, "Cargo.toml")?.or_else(|| cargo_root.clone())
380	    } else {
381	        None
382	    };
383	    let base_versions = ws.base_versions()?;
384	    for pkg in ws.graph.packages() {
385	        let Some(disk) = base_versions.get(&pkg.id) else {
386	            continue;
387	        };
388	        for decl in pkg.canonical_manifests() {
389	            let path = super::release_decision::normalized_git_path(&decl.path)?;
390	            let Some(head_version) = manifest_version_at(ws, head, &path, cargo_root.as_deref())? else {
391	                continue;
392	            };
393	            let index_path_changed = staged_manifests.contains(&path)
394	                || (decl.ecosystem() == callisto_model::Ecosystem::Cargo && staged_manifests.contains("Cargo.toml"));
395	            let index_version = if index_path_changed {
396	                manifest_version_in_index(ws, &path, cargo_root_index.as_deref())?
397	            } else {
398	                None
399	            };
400	            let index_display = match &index_version {
401	                Some(version) => version.version.render().to_string(),
402	                None if index_path_changed => "absent".to_string(),
403	                None => head_version.version.render().to_string(),
404	            };
405	            let index_differs = index_path_changed
406	                && index_version
407	                    .as_ref()
408	                    .is_none_or(|version| version.version != head_version.version);
409	            let completing_prerelease = pre_mode == Some(callisto_model::format::PreMode::Exit)
410	                && disk.is_prerelease()
411	                && (!index_path_changed
412	                    || index_version
413	                        .as_ref()
414	                        .is_some_and(|version| version.version.is_prerelease()));
415	            if completing_prerelease {
416	                continue;
417	            }
418	            if *disk != head_version.version || index_differs {
419	                return Err(GraphError::PartialVersionRun {
420	                    path: head_version.authority,
421	                    disk: disk.clone(),
422	                    index: index_display,
423	                    head: head_version.version,
424	                });
425	            }
426	        }
427	    }
428	
429	    Ok(())
430	}
