 22	fn run_schema(target: &str) -> serde_json::Value {
 23	    let bin = env!("CARGO_BIN_EXE_callisto");
 24	    let out = Command::new(bin)
 25	        .args(["schema", "--type", target])
 26	        .output()
 27	        .expect("callisto schema must run");
 28	    assert!(
 29	        out.status.success(),
 30	        "callisto schema --type {target} failed: {}",
 31	        String::from_utf8_lossy(&out.stderr)
 32	    );
 33	    serde_json::from_slice(&out.stdout).expect("schema output must be valid JSON")
 34	}
