 36	fn required_and_props(schema: &serde_json::Value) -> (BTreeSet<String>, BTreeSet<String>) {
 37	    let required: BTreeSet<String> = schema["required"]
 38	        .as_array()
 39	        .unwrap()
 40	        .iter()
 41	        .map(|v| v.as_str().unwrap().to_string())
 42	        .collect();
 43	    let props: BTreeSet<String> = schema["properties"].as_object().unwrap().keys().cloned().collect();
 44	    (required, props)
 45	}
