305	fn receipt() -> ReleaseReceiptV1 {
306	    let package = ReleasePackageId::parse("cargo/widget-core").unwrap();
307	    let version = Version::semver(1, 3, 0);
308	    let revision = CommitSha::parse(&"a".repeat(40)).unwrap();
309	    let registry = RegistryBindingId::new("cratesIo", RegistryBindingDigest::parse(&"b".repeat(64)).unwrap()).unwrap();
310	    let publish = ReleaseOperation::registry_publish(package.clone(), version.clone(), registry, vec![]).unwrap();
311	    let tag = ReleaseOperation::tag(package.clone(), version.clone(), vec![publish.id().clone()]).unwrap();
312	    let decision = ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
313	        package: package.clone(),
314	        target_version: version.clone(),
315	        reasons: vec![ReleaseInclusionReason::Changeset],
316	    }])
317	    .unwrap();
318	    let snapshot = ReleaseInputSnapshotV1::new(
319	        SourceIdentity::GitCommit { sha: revision.clone() },
320	        vec![ReleasePackageInputV1 {
321	            package,
322	            fingerprint: SemanticInputDigest::parse(&"c".repeat(64)).unwrap(),
323	        }],
324	    )
325	    .unwrap();
326	    let intent = ReleaseIntentV1::new(
327	        decision,
328	        snapshot,
329	        ExecutionTrustProfileV1::GitCommit,
330	        vec![publish.clone(), tag.clone()],
331	        vec![],
332	    )
333	    .unwrap();
334	    let envelope = ReleaseRunEnvelopeV1::new(revision.clone(), &intent, None).unwrap();
335	    let mut state = ReleaseExecutionStateV1::new(&intent, envelope).unwrap();
336	    for (operation, evidence) in [
337	        (
338	            publish,
339	            ProviderEvidenceV1::RegistryVersion {
340	                version,
341	                checksum: Some(ArtifactDigest::parse(&"d".repeat(64)).unwrap()),
342	                yanked: Some(false),
343	            },
344	        ),
345	        (
346	            tag,
347	            ProviderEvidenceV1::GitTag {
348	                peeled_commit: revision,
349	            },
350	        ),
351	    ] {
352	        let observation = ProviderObservationV1::Exact { evidence };
353	        state
354	            .apply(
355	                operation.id(),
356	                &OperationEvent::ObservedExactBeforeEffect {
357	                    evidence: observation.exact_evidence().unwrap(),
358	                },
359	            )
360	            .unwrap();
361	    }
362	    ReleaseReceiptV1::from_state(&intent, &state).unwrap()
363	}
