    11	pub fn handle(args: SchemaArgs, _global: &GlobalArgs) -> Result<ExitCode, CliError> {
    12	    let schema = match args.target_type.unwrap_or_default() {
    13	        SchemaReportType::Status => schema_for!(StatusReport),
    14	        SchemaReportType::Version => schema_for!(VersionReport),
    15	        SchemaReportType::Snapshot => schema_for!(SnapshotReport),
    16	        SchemaReportType::Init => schema_for!(InitReport),
    17	        SchemaReportType::Changeset => schema_for!(Changeset),
    18	        SchemaReportType::PreState => schema_for!(PreState),
    19	        SchemaReportType::Matrix => schema_for!(MatrixReport),
    20	        SchemaReportType::ReleaseReceipt => schema_for!(ReleaseReceiptV1),
    21	    };
