    23	    // A `schemars::Schema` is a plain JSON tree of strings, numbers, and nested maps;
    24	    // it always serializes.
    25	    let json = serde_json::to_string_pretty(&schema).expect("schema serializes");
    26	    write_stdout(format!("{json}\n").as_bytes())?;
    27	    Ok(ExitCode::SUCCESS)
