  20	/// `callisto.toml` value authored on Windows reads back as one literal,
  21	/// oddly-named path component on POSIX. Callers taking a config value
  22	/// (`[changesets].dir`, `[[package]] changelog`) must document that the
  23	/// value should always use `/` regardless of authoring platform -- this
  24	/// function can't enforce that for them.
  25	pub fn workspace_relative(path: impl AsRef<Path>) -> Result<PathBuf, ModelError> {
  26	    let p = path.as_ref();
  27	    if p.is_absolute() {
  28	        return Err(ModelError::AbsolutePath { path: p.to_path_buf() });
  29	    }
  30	
  31	    let utf8 = Utf8PathBuf::from_path_buf(p.to_path_buf()).map_err(|path| ModelError::NonUtf8Path { path })?;
  32	
  33	    // `to_slash()` can only return `None` for non-UTF-8 input, which `utf8` has
  34	    // already ruled out -- unreachable in practice, kept as a typed error path
  35	    // rather than a panic in case that invariant ever changes upstream.
  36	    let slash_str = utf8.as_std_path().to_slash().ok_or_else(|| ModelError::NonUtf8Path {
  37	        path: utf8.as_std_path().to_path_buf(),
  38	    })?;
  39	    let normalized_path = Path::new(slash_str.as_ref());
  40	
  41	    let mut components = Vec::new();
  42	    for component in normalized_path.components() {
  43	        match component {
  44	            Component::Prefix(_) | Component::RootDir => {
  45	                return Err(ModelError::AbsolutePath { path: p.to_path_buf() });
  46	            }
  47	            Component::CurDir => {}
  48	            Component::ParentDir => {
  49	                if let Some(Component::Normal(_)) = components.last() {
  50	                    components.pop();
  51	                } else {
  52	                    return Err(ModelError::PathTraversal { path: p.to_path_buf() });
  53	                }
  54	            }
  55	            Component::Normal(_) => {
  56	                components.push(component);
  57	            }
  58	        }
  59	    }
  60	
  61	    let mut out_str = String::new();
  62	    for (i, c) in components.iter().enumerate() {
  63	        if i > 0 {
  64	            out_str.push('/');
  65	        }
  66	        out_str.push_str(c.as_os_str().to_str().unwrap());
  67	    }
  68	
  69	    Ok(PathBuf::from(out_str))
  70	}
